1	"use client";
2	
3	/**
4	 * PREVIEW TEMPLATE — "Shared web hosting" (WordPress / one-click managed).
5	 *
6	 * Hero centerpiece: an animated one-click WordPress install that resolves to a
7	 * light browser frame populating with a live WordPress-style site ("site live in
8	 * seconds"). Distinct wedges: a flat-pricing chart that contrasts a typical
9	 * host's renewal spike against Nxeon's flat price ("no renewal price hikes" — a
10	 * real SERP trust wedge), a cPanel-class control-panel product screen, a
11	 * one-click apps marquee, a free-migration flow shown honestly (handled vs
12	 * flagged), and compact reviews. Asymmetric and editorial — never a centered
13	 * stack.
14	 *
15	 * Net-new, preview-only. Touches no live page or shared component (ScreenFrame /
16	 * UsageBar are imported read-only from the shared showcase kit).
17	 */
18	
19	import Link from "next/link";
20	import { useEffect, useRef, useState } from "react";
21	import styles from "./webhosting.module.css";
22	import { usePrefersReducedMotion, useInViewOnce, useCountUp, StarRow, LiveDot } from "./kit";
23	import { FeatureIcon } from "./icons-map";
24	import {
25	  INSTALL_STEPS,
26	  PANEL_TILES,
27	  FEATURES,
28	  PRICE_YEARS,
29	  PLANS,
30	  MIGRATION_STEPS,
31	  ONE_CLICK_APPS,
32	  REVIEWS,
33	  RATING_AVG,
34	  RATING_LABEL,
35	} from "./data";
36	import { ScreenFrame, UsageBar } from "@/components/marketing/showcase/Frame";
37	import { IconCheck, IconArrow, IconBolt, IconApps, IconGlobe } from "@/components/marketing/icons";
38	
39	/* ── Hero centerpiece: one-click install → live site ─────────────────────── */
40	function InstallToLive() {
41	  const reduced = usePrefersReducedMotion();
42	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
43	  const [installed, setInstalled] = useState(0);
44	  const [phase, setPhase] = useState<"idle" | "installing" | "live">("idle");
45	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
46	
47	  useEffect(() => {
48	    if (!seen) return;
49	    if (reduced) {
50	      setInstalled(INSTALL_STEPS.length);
51	      setPhase("live");
52	      return;
53	    }
54	    let dead = false;
55	    const push = (fn: () => void, ms: number) => {
56	      if (!dead) timers.current.push(setTimeout(fn, ms));
57	    };
58	    const run = () => {
59	      setInstalled(0);
60	      setPhase("installing");
61	      INSTALL_STEPS.forEach((_, i) => push(() => setInstalled(i + 1), 600 + 720 * (i + 1)));
62	      const done = 600 + 720 * (INSTALL_STEPS.length + 1);
63	      push(() => setPhase("live"), done);
64	      push(run, done + 5200); // loop
65	    };
66	    run();
67	    return () => {
68	      dead = true;
69	      timers.current.forEach(clearTimeout);
70	      timers.current = [];
71	    };
72	  }, [seen, reduced]);
73	
74	  const live = phase === "live";
75	
76	  return (
77	    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
78	      <div className="relative grid gap-4 sm:grid-cols-[0.92fr_1.08fr] sm:items-start">
79	        <div
80	          className="pointer-events-none absolute -inset-10 -z-10 opacity-70"
81	          style={{
82	            background:
83	              "radial-gradient(45% 45% at 10% 0%, rgba(59,130,246,0.20), transparent 70%), radial-gradient(45% 50% at 95% 100%, rgba(111,71,245,0.22), transparent 70%)",
84	          }}
85	          aria-hidden
86	        />
87	
88	        {/* install panel */}
89	        <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/90 shadow-2xl shadow-black/50 backdrop-blur-xl">
90	          <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
91	            <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-white">
92	              <IconApps size={13} />
93	            </span>
94	            <span className="text-[12px] font-medium text-slate-300">One-click installer</span>
95	            <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
96	              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
97	              {live ? "installed" : "installing"}
98	            </span>
99	          </div>
100	          <div className="space-y-3 px-4 py-4">
101	            <div className="flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
102	              <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-white/[0.04] text-brand-300">
103	                <IconApps size={18} />
104	              </span>
105	              <span>
106	                <span className="block text-sm font-semibold text-white">WordPress</span>
107	                <span className="block text-[11px] text-slate-500">yoursite.com</span>
108	              </span>
109	              <span className="ml-auto text-[11px] font-medium text-slate-500">1-click</span>
110	            </div>
111	            <ul className="space-y-1.5 font-mono text-[12px]">
112	              {INSTALL_STEPS.map((s, i) => {
113	                const done = installed > i;
114	                return (
115	                  <li key={s.label} className={`flex items-center gap-2 ${done ? "text-slate-300" : "text-slate-600"}`}>
116	                    <span
117	                      className={`flex h-3.5 w-3.5 shrink-0 items-center justify-center rounded-full ${
118	                        done ? "bg-emerald-500/15 text-emerald-400" : "border border-white/10 text-transparent"
119	                      }`}
120	                    >
121	                      <IconCheck size={10} />
122	                    </span>
123	                    <span className="flex-1">{s.label}</span>
124	                    <span className="text-slate-600">{s.detail}</span>
125	                  </li>
126	                );
127	              })}
128	            </ul>
129	            <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
130	              <div
131	                className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-[width] duration-500 ease-out"
132	                style={{ width: `${(installed / INSTALL_STEPS.length) * 100}%` }}
133	              />
134	            </div>
135	          </div>
136	        </div>
137	
138	        {/* live browser preview */}
139	        <div className="relative">
140	          <div className="overflow-hidden rounded-2xl border border-white/10 bg-white shadow-2xl shadow-black/40">
141	            <div className="flex items-center gap-2 border-b border-black/10 bg-slate-100 px-3 py-2">
142	              <span className="h-2.5 w-2.5 rounded-full bg-[#ff5f57]" />
143	              <span className="h-2.5 w-2.5 rounded-full bg-[#febc2e]" />
144	              <span className="h-2.5 w-2.5 rounded-full bg-[#28c840]" />
145	              <span className="ml-2 flex flex-1 items-center gap-1.5 truncate rounded-md bg-white px-2.5 py-1 text-[10px] text-slate-500 ring-1 ring-black/5">
146	                <span className="text-emerald-600">🔒</span>
147	                {live ? "https://yoursite.com" : "installing…"}
148	              </span>
149	            </div>
150	            <div className="relative min-h-[256px] bg-white">
151	              {!live ? (
152	                <div className="flex min-h-[256px] flex-col items-center justify-center gap-3 px-6 text-center">
153	                  <span className="flex h-9 w-9 items-center justify-center rounded-full border-2 border-brand-500/30 border-t-brand-500 motion-safe:animate-orbit-spin" />
154	                  <p className="text-[12px] font-medium text-slate-400">Building your site…</p>
155	                </div>
156	              ) : (
157	                <div>
158	                  {/* WordPress-style site */}
159	                  <div
160	                    className={`flex items-center justify-between border-b border-slate-100 px-4 py-2.5 ${reduced ? "" : styles.rise}`}
161	                    style={{ animationDelay: "0ms" }}
162	                  >
163	                    <span className="text-[13px] font-bold tracking-tight text-slate-800">Meridian &amp; Co.</span>
164	                    <div className="hidden gap-2 text-[9px] font-medium text-slate-500 sm:flex">
165	                      <span>Home</span>
166	                      <span>Work</span>
167	                      <span>About</span>
168	                      <span className="rounded-full bg-slate-900 px-2 py-0.5 text-white">Contact</span>
169	                    </div>
170	                  </div>
171	                  <div
172	                    className={`bg-gradient-to-b from-slate-50 to-white px-4 py-5 text-center ${reduced ? "" : styles.rise}`}
173	                    style={{ animationDelay: "90ms" }}
174	                  >
175	                    <p className="text-[9px] font-semibold uppercase tracking-[0.2em] text-brand-600">Studio</p>
176	                    <h4 className="mx-auto mt-1 max-w-[16rem] text-base font-bold leading-tight text-slate-900">
177	                      We design brands people remember.
178	                    </h4>
179	                    <span className="mt-2.5 inline-block rounded-full bg-slate-900 px-3 py-1 text-[10px] font-semibold text-white">
180	                      Start a project
181	                    </span>
182	                  </div>
183	                  <div className="grid grid-cols-3 gap-2 px-4 pb-4">
184	                    {["Branding", "Web", "Motion"].map((s, i) => (
185	                      <div
186	                        key={s}
187	                        className={`rounded-lg border border-slate-100 bg-white p-2 text-left shadow-sm ${reduced ? "" : styles.rise}`}
188	                        style={{ animationDelay: `${180 + i * 90}ms` }}
189	                      >
190	                        <div className="mb-1.5 h-6 rounded bg-gradient-to-br from-brand-100 to-slate-100" />
191	                        <p className="text-[9px] font-semibold text-slate-700">{s}</p>
192	                      </div>
193	                    ))}
194	                  </div>
195	                </div>
196	              )}
197	            </div>
198	          </div>
199	          <div className="mt-3 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.04] px-3 py-1.5 text-[12px] text-slate-300 backdrop-blur-md">
200	            <LiveDot />
201	            {live ? (
202	              <>
203	                <span className="font-semibold text-accent-cyan">Live</span> · free SSL issued · under a minute
204	              </>
205	            ) : (
206	              <>Provisioning your site…</>
207	            )}
208	          </div>
209	        </div>
210	      </div>
211	    </div>
212	  );
213	}
214	
215	/* ── Flat-pricing wedge: renewal spike vs flat ───────────────────────────── */
216	function FlatPriceChart() {
217	  const reduced = usePrefersReducedMotion();
218	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
219	  const max = Math.max(...PRICE_YEARS.flatMap((y) => [y.nxeon, y.typical]));
220	  const h = (v: number) => `${Math.max(12, (v / max) * 100)}%`;
221	
222	  return (
223	    <div ref={ref} className="grid gap-10 lg:grid-cols-2 lg:items-center lg:gap-14">
224	      <div>
225	        <span className="eyebrow">No renewal price hikes</span>
226	        <h2 className="mt-3 text-3xl font-bold tracking-tight text-white sm:text-4xl">
227	          The price you sign up at is the <span className="grad-text">price you renew at</span>
228	        </h2>
229	        <p className="mt-4 max-w-md text-lg leading-relaxed text-slate-400">
230	          Most hosts hook you with a low first-year price, then quietly double or triple it at renewal. We don&apos;t. Your
231	          rate stays exactly the same, year after year.
232	        </p>
233	        <div className="mt-6 inline-flex items-center gap-3 rounded-2xl border border-accent-cyan/25 bg-accent-cyan/[0.06] px-4 py-3">
234	          <LiveDot />
235	          <span className="text-sm text-slate-200">
236	            <span className="font-bold text-accent-cyan">$5.99</span> at signup ={" "}
237	            <span className="font-bold text-accent-cyan">$5.99</span> at renewal — always.
238	          </span>
239	        </div>
240	        <div className="mt-6 flex items-center gap-5 text-xs text-slate-400">
241	          <span className="inline-flex items-center gap-1.5">
242	            <span className="h-2.5 w-2.5 rounded-sm bg-gradient-to-t from-brand-500 to-accent-cyan" /> Nxeon
243	          </span>
244	          <span className="inline-flex items-center gap-1.5">
245	            <span className="h-2.5 w-2.5 rounded-sm bg-gradient-to-t from-rose-500/70 to-amber-400/70" /> A typical host
246	          </span>
247	        </div>
248	      </div>
249	
250	      {/* bar chart */}
251	      <div className="rounded-2xl border border-white/[0.07] bg-navy-900/50 p-6 backdrop-blur-md">
252	        <div className="grid grid-cols-3 gap-5">
253	          {PRICE_YEARS.map((y, gi) => (
254	            <div key={y.year} className="flex flex-col items-center">
255	              <div className="flex h-44 w-full items-end justify-center gap-2">
256	                {/* Nxeon — flat */}
257	                <div className="flex h-full flex-1 flex-col items-center justify-end">
258	                  <span className="mb-1 font-mono text-[11px] font-semibold text-accent-cyan tabular-nums">${y.nxeon}</span>
259	                  <div
260	                    className={`w-full rounded-t-md bg-gradient-to-t from-brand-500 to-accent-cyan ${
261	                      reduced || !seen ? "" : styles.bar
262	                    }`}
263	                    style={
264	                      {
265	                        height: reduced || seen ? h(y.nxeon) : 0,
266	                        "--wh-h": h(y.nxeon),
267	                        animationDelay: `${gi * 140}ms`,
268	                      } as React.CSSProperties
269	                    }
270	                  />
271	                </div>
272	                {/* Typical — hikes */}
273	                <div className="flex h-full flex-1 flex-col items-center justify-end">
274	                  <span className="mb-1 font-mono text-[11px] font-semibold text-rose-300 tabular-nums">${y.typical}</span>
275	                  <div
276	                    className={`w-full rounded-t-md bg-gradient-to-t from-rose-500/70 to-amber-400/70 ${
277	                      reduced || !seen ? "" : styles.bar
278	                    }`}
279	                    style={
280	                      {
281	                        height: reduced || seen ? h(y.typical) : 0,
282	                        "--wh-h": h(y.typical),
283	                        animationDelay: `${gi * 140 + 90}ms`,
284	                      } as React.CSSProperties
285	                    }
286	                  />
287	                </div>
288	              </div>
289	              <span className="mt-3 text-[11px] font-medium text-slate-500">{y.year}</span>
290	            </div>
291	          ))}
292	        </div>
293	        <p className="mt-5 border-t border-white/[0.06] pt-4 text-center text-xs text-slate-500">
294	          Illustrative comparison · monthly-equivalent price at renewal
295	        </p>
296	      </div>
297	    </div>
298	  );
299	}
300	
301	/* ── cPanel-class control panel product screen ───────────────────────────── */
302	function ControlPanelScreen() {
303	  const reduced = usePrefersReducedMotion();
304	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
305	  const visitors = useCountUp(3420, seen, 1300, reduced);
306	  const nav = ["Dashboard", "Websites", "Files", "Databases", "Email", "Domains", "SSL", "Backups"];
307	
308	  // tiny sparkline
309	  const pts = [8, 10, 9, 12, 11, 14, 13, 16, 15, 18, 17, 20];
310	  const w = 120;
311	  const sh = 34;
312	  const min = 6;
313	  const max = 22;
314	  const step = w / (pts.length - 1);
315	  const line = pts
316	    .map((v, i) => `${i === 0 ? "M" : "L"}${(i * step).toFixed(1)} ${(sh - ((v - min) / (max - min)) * sh).toFixed(1)}`)
317	    .join(" ");
318	
319	  return (
320	    <div ref={ref}>
321	      <ScreenFrame title="yoursite.com · control panel" icon={<IconGlobe size={12} />} live>
322	        <div className="grid gap-0 sm:grid-cols-[150px_1fr]">
323	          {/* sidebar */}
324	          <div className="hidden flex-col gap-0.5 border-r border-white/[0.06] bg-white/[0.02] p-3 sm:flex">
325	            {nav.map((n, i) => (
326	              <span
327	                key={n}
328	                className={`flex items-center gap-2 rounded-lg px-2.5 py-1.5 text-[12px] ${
329	                  i === 0 ? "bg-brand-500/15 font-medium text-brand-200" : "text-slate-400"
330	                }`}
331	              >
332	                <span className={`h-1.5 w-1.5 rounded-full ${i === 0 ? "bg-brand-400" : "bg-white/15"}`} />
333	                {n}
334	              </span>
335	            ))}
336	          </div>
337	
338	          {/* main */}
339	          <div className="p-4">
340	            {/* stat row */}
341	            <div className="grid grid-cols-3 gap-2.5">
342	              <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
343	                <p className="text-[10px] uppercase tracking-wide text-slate-500">Disk</p>
344	                <p className="mt-1 font-mono text-sm font-semibold text-white">6.4 / 20 GB</p>
345	                <UsageBar pct={32} delay={200} className="mt-2" />
346	              </div>
347	              <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
348	                <p className="text-[10px] uppercase tracking-wide text-slate-500">Visitors · 30d</p>
349	                <p className="mt-1 font-mono text-sm font-semibold text-white tabular-nums">{visitors.toLocaleString()}</p>
350	                <svg viewBox={`0 0 ${w} ${sh}`} className="mt-1.5 h-[26px] w-full" preserveAspectRatio="none" aria-hidden>
351	                  <path d={line} fill="none" stroke="var(--color-accent-cyan)" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className={reduced || !seen ? "" : "pv-draw"} />
352	                </svg>
353	              </div>
354	              <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
355	                <p className="text-[10px] uppercase tracking-wide text-slate-500">SSL</p>
356	                <p className="mt-1 inline-flex items-center gap-1.5 font-mono text-sm font-semibold text-emerald-300">
357	                  <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" /> Active
358	                </p>
359	                <p className="mt-2 text-[10px] text-slate-500">auto-renews</p>
360	              </div>
361	            </div>
362	
363	            {/* tools grid */}
364	            <div className="mt-3 grid grid-cols-2 gap-2.5 sm:grid-cols-3">
365	              {PANEL_TILES.map((t, i) => (
366	                <div
367	                  key={t.label}
368	                  className={`flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] p-2.5 transition-colors hover:border-white/15 ${
369	                    reduced ? "" : "motion-safe:animate-fade-up"
370	                  }`}
371	                  style={{ animationDelay: `${i * 70}ms` }}
372	                >
373	                  <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-gradient-to-br from-brand-500/25 to-transparent text-brand-300">
374	                    <FeatureIcon icon={t.icon} size={16} />
375	                  </span>
376	                  <span className="min-w-0">
377	                    <span className="block truncate text-[12px] font-medium text-white">{t.label}</span>
378	                    <span className="block truncate text-[10px] text-slate-500">{t.sub}</span>
379	                  </span>
380	                </div>
381	              ))}
382	            </div>
383	          </div>
384	        </div>
385	      </ScreenFrame>
386	    </div>
387	  );
388	}
389	
390	/* ── One-click apps marquee ──────────────────────────────────────────────── */
391	function AppsRibbon() {
392	  return (
393	    <div className={`${styles.marquee} relative overflow-hidden`}>
394	      <div className="pointer-events-none absolute inset-y-0 left-0 z-10 w-24 bg-gradient-to-r from-navy-950 to-transparent" aria-hidden />
395	      <div className="pointer-events-none absolute inset-y-0 right-0 z-10 w-24 bg-gradient-to-l from-navy-950 to-transparent" aria-hidden />
396	      <div className={styles.marqueeTrack} aria-hidden>
397	        {[...ONE_CLICK_APPS, ...ONE_CLICK_APPS].map((t, i) => (
398	          <span
399	            key={i}
400	            className="mx-1.5 shrink-0 rounded-full border border-white/[0.07] bg-white/[0.02] px-4 py-1.5 text-sm font-medium text-slate-400"
401	          >
402	            {t}
403	          </span>
404	        ))}
405	      </div>
406	    </div>
407	  );
408	}
409	
410	/* ── Migration flow (handled vs flagged, honest) ─────────────────────────── */
411	function MigrationFlow() {
412	  const reduced = usePrefersReducedMotion();
413	  const { ref, seen } = useInViewOnce<HTMLDivElement>();
414	  const [shown, setShown] = useState(reduced ? MIGRATION_STEPS.length : 0);
415	
416	  useEffect(() => {
417	    if (!seen) return;
418	    if (reduced) {
419	      setShown(MIGRATION_STEPS.length);
420	      return;
421	    }
422	    let i = 0;
423	    let t: ReturnType<typeof setTimeout>;
424	    const tick = () => {
425	      i += 1;
426	      setShown(i);
427	      if (i < MIGRATION_STEPS.length) t = setTimeout(tick, 620);
428	    };
429	    t = setTimeout(tick, 500);
430	    return () => clearTimeout(t);
431	  }, [seen, reduced]);
432	
433	  return (
434	    <div ref={ref} className="rounded-2xl border border-white/10 bg-black/40 p-5 font-mono text-[12.5px] leading-relaxed shadow-2xl">
435	      <div className="mb-3 flex items-center gap-1.5">
436	        <span className="h-2.5 w-2.5 rounded-full bg-red-500/70" />
437	        <span className="h-2.5 w-2.5 rounded-full bg-amber-400/70" />
438	        <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
439	        <span className="ml-2 text-[11px] uppercase tracking-widest text-slate-500">nxeon · migrate</span>
440	      </div>
441	      <div className="min-h-[152px] space-y-1.5">
442	        {MIGRATION_STEPS.slice(0, shown).map((s, i) => (
443	          <div key={i} className="flex items-center gap-2">
444	            {s.status === "done" ? (
445	              <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
446	                <IconCheck size={11} />
447	              </span>
448	            ) : (
449	              <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-amber-400/15 text-amber-300">!</span>
450	            )}
451	            <span className={s.status === "flagged" ? "text-amber-200" : "text-slate-300"}>{s.label}</span>
452	          </div>
453	        ))}
454	        {shown >= MIGRATION_STEPS.length && (
455	          <div className="mt-2 flex items-center gap-2 rounded-lg border border-emerald-400/20 bg-emerald-400/[0.06] px-3 py-2 text-[11.5px] text-emerald-300">
