3	/**
4	 * Co-located client kit for the shared web-hosting PREVIEW template
5	 * (components/marketing/webhostingtemplate/*). Self-contained hooks + atoms so
6	 * the template is isolated and independently shippable. Everything respects
7	 * prefers-reduced-motion: motion hooks resolve to their final resting value.
8	 *
9	 * Net-new, preview-only. Touches no live page or shared component.
10	 */
11	
12	import { useEffect, useRef, useState } from "react";
13	
14	export function usePrefersReducedMotion() {
15	  const [reduced, setReduced] = useState(false);
16	  useEffect(() => {
17	    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
18	    if (!mq) return;
19	    setReduced(mq.matches);
20	    const on = () => setReduced(mq.matches);
21	    mq.addEventListener?.("change", on);
22	    return () => mq.removeEventListener?.("change", on);
23	  }, []);
24	  return reduced;
25	}
26	
27	/** Fires once when the element first scrolls into view. */
28	export function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
29	  const ref = useRef<T | null>(null);
30	  const [seen, setSeen] = useState(false);
31	  useEffect(() => {
32	    const el = ref.current;
33	    if (!el || typeof IntersectionObserver === "undefined") {
34	      setSeen(true);
35	      return;
36	    }
37	    const io = new IntersectionObserver(
38	      ([e]) => {
39	        if (e.isIntersecting) {
40	          setSeen(true);
41	          io.disconnect();
42	        }
43	      },
44	      { threshold: 0.2, rootMargin: margin },
45	    );
46	    io.observe(el);
47	    return () => io.disconnect();
48	  }, [margin]);
49	  return { ref, seen };
50	}
51	
52	/** Smoothly counts up to `target` once `active`. Immediate under reduced motion. */
53	export function useCountUp(target: number, active: boolean, duration = 1100, reduced = false) {
54	  const [val, setVal] = useState(reduced ? target : 0);
55	  useEffect(() => {
56	    if (!active) return;
57	    if (reduced) {
58	      setVal(target);
59	      return;
60	    }
61	    let raf = 0;
62	    const start = performance.now();
63	    const tick = (now: number) => {
64	      const t = Math.min(1, (now - start) / duration);
65	      const eased = 1 - Math.pow(1 - t, 3);
66	      setVal(Math.round(target * eased));
67	      if (t < 1) raf = requestAnimationFrame(tick);
68	    };
69	    raf = requestAnimationFrame(tick);
70	    return () => cancelAnimationFrame(raf);
71	  }, [target, active, duration, reduced]);
72	  return val;
73	}
74	
75	/** Compact amber 5-star row (matches the shipped ReviewCarousel/StarRow treatment). */
76	export function StarRow({ rating = 5, size = "text-sm" }: { rating?: number; size?: string }) {
77	  const filled = Math.max(0, Math.min(5, rating));
78	  return (
79	    <span className={`tracking-[0.12em] ${size}`} aria-label={`${filled} out of 5 stars`}>
80	      <span className="text-amber-300">{"★".repeat(filled)}</span>
81	      <span className="text-white/15">{"★".repeat(5 - filled)}</span>
82	    </span>
83	  );
84	}
85	
86	/** A pulsing cyan "live" dot — the in-theme active/live pop. */
87	export function LiveDot({ className = "" }: { className?: string }) {
88	  return (
89	    <span className={`relative flex h-2.5 w-2.5 ${className}`}>
90	      <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-accent-cyan/60 motion-reduce:hidden" />
91	      <span className="relative inline-flex h-2.5 w-2.5 rounded-full bg-accent-cyan" />
92	    </span>
93	  );
94	}
