50	/* ── Live TPS sparkline — draws on view, pulsing playhead (from Cinematic) ── */
51	function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
52	  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
53	  const w = 220;
54	  const h = 46;
55	  const min = 19.5;
56	  const max = 20.2;
57	  const step = w / (pts.length - 1);
58	  const coords = pts.map((v, i) => {
59	    const x = i * step;
60	    const y = h - ((v - min) / (max - min)) * h;
61	    return [x, y] as const;
62	  });
63	  const line = coords.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
64	  const area = `${line} L${w} ${h} L0 ${h} Z`;
65	  const [ex, ey] = coords[coords.length - 1];
66	  return (
67	    <svg viewBox={`0 0 ${w} ${h}`} className="h-[46px] w-full" preserveAspectRatio="none" aria-hidden>
68	      <defs>
69	        <linearGradient id="pv-cmb-tps-fill" x1="0" y1="0" x2="0" y2="1">
70	          <stop offset="0%" stopColor={accent} stopOpacity="0.35" />
71	          <stop offset="100%" stopColor={accent} stopOpacity="0" />
72	        </linearGradient>
73	      </defs>
74	      <path d={area} fill="url(#pv-cmb-tps-fill)" />
75	      <path
76	        d={line}
77	        fill="none"
78	        stroke={accent}
79	        strokeWidth="1.6"
80	        strokeLinecap="round"
81	        strokeLinejoin="round"
82	        className={reduced || !active ? "" : "pv-draw"}
83	      />
84	      <circle cx={ex} cy={ey} r="3" fill={accent} className={reduced ? "" : "motion-safe:animate-pulse-dot"} />
85	    </svg>
86	  );
87	}
