3	function JsonLd({ data }: { data: Record<string, unknown> }) {
4	  return (
5	    <script
6	      type="application/ld+json"
7	      // JSON.stringify output is safe to inline; no user input here.
8	      dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
9	    />
