170	/** Article markup for blog posts. */
171	export function ArticleJsonLd({
172	  title,
173	  description,
174	  slug,
175	  published,
176	  updated,
177	  author,
178	  image,
179	}: {
180	  title: string;
181	  description: string;
182	  slug: string;
183	  published: string;
184	  updated: string;
185	  author: string;
186	  /** Absolute or root-relative cover image URL, if the post has one. */
187	  image?: string | null;
188	}) {
189	  const url = `${APP_URL}/blog/${slug}`;
190	  // Normalise a root-relative cover to an absolute URL — Google requires an
191	  // absolute image URL in the Article markup.
192	  const imageUrl = image ? (image.startsWith("http") ? image : `${APP_URL}${image}`) : undefined;
193	  return (
194	    <JsonLd
195	      data={{
196	        "@context": "https://schema.org",
197	        "@type": "BlogPosting",
198	        headline: title,
199	        description,
200	        url,
201	        // Ties the rich result to this exact canonical page.
202	        mainEntityOfPage: { "@type": "WebPage", "@id": url },
203	        ...(imageUrl ? { image: imageUrl } : {}),
204	        datePublished: published,
205	        dateModified: updated,
206	        author: { "@type": "Organization", name: author },
207	        publisher: {
208	          "@type": "Organization",
209	          name: "Nxeon",
210	          logo: { "@type": "ImageObject", url: `${APP_URL}/logo.png` },
211	        },
212	      }}
213	    />
214	  );
215	}
