"use client";

/**
 * PREVIEW TEMPLATE — "Shared web hosting" (WordPress / one-click managed).
 *
 * OVERHAULED for a beginner audience (2026-08-31). Shared hosting is bought by
 * people who have never run a server, so this page is deliberately friendly and
 * low-jargon: it leans on real *product-screen* visuals — a browser/site frame
 * assembling a live site, a clean control-panel dashboard, and the animated
 * <MigrationScreens/> motion graphic — instead of terminals or code logs.
 *
 * Distinct wedges, all asymmetric/editorial (never a centered stack):
 *   • hero — a friendly "one click → site live" beat (plain-language setup card
 *     resolving into a light browser frame that populates with a real-looking
 *     site), plus the live <ReviewBadges/> strip for social proof.
 *   • flat-pricing — the "no renewal price hikes" comparison, rebuilt on-brand
 *     (Nxeon = violet→cyan; a typical host = amber, used only as the semantic
 *     "price hike" warning) with gridlines and a flat-forever guide line.
 *   • control panel — a cPanel-class product screen (files, email, SSL, backups).
 *   • one-click apps marquee, then the honest free-migration beat shown with the
 *     shared <MigrationScreens/> animation, an everything-included feature grid,
 *     flat plans, a beginner FAQ, and a closing CTA.
 *
 * Every outer glow is a soft, feathered radial that bleeds into the background
 * (blur, radial fade to transparent, rendered OUTSIDE the panel's overflow clip)
 * so there is never a hard rectangular cutoff. Everything respects
 * prefers-reduced-motion. Net-new, preview-only; touches no live page (imports
 * ScreenFrame / UsageBar / MigrationScreens / ReviewBadges / icons read-only).
 */

import Link from "next/link";
import type { ReactNode } from "react";
import { useEffect, useRef, useState } from "react";
import styles from "./webhosting.module.css";
import { usePrefersReducedMotion, useInViewOnce, useCountUp, LiveDot } from "./kit";
import { FeatureIcon } from "./icons-map";
import { INSTALL_STEPS, PANEL_TILES, FEATURES, PRICE_YEARS, PLANS, ONE_CLICK_APPS, REVIEWS, FAQS } from "./data";
import { ScreenFrame, UsageBar } from "@/components/marketing/showcase/Frame";
import { MigrationScreens } from "@/components/marketing/showcase/MigrationScreens";
import {
  IconCheck,
  IconArrow,
  IconBolt,
  IconApps,
  IconGlobe,
  IconLock,
  IconShield,
  IconClock,
  IconSupport,
  IconMail,
} from "@/components/marketing/icons";

/* ── Soft feathered glow — a blurred radial that bleeds into the background ──
   The fix for the "sharp-cutoff" glow-box: rendered as a sibling BEHIND the
   panel (never inside its overflow:hidden clip), blurred, and colour-faded to
   transparent well within its own bounds, so there is no hard rectangular edge. */
function AuraGlow({
  className = "",
  gradient,
  breathe = true,
}: {
  className?: string;
  gradient: string;
  breathe?: boolean;
}) {
  const reduced = usePrefersReducedMotion();
  return (
    <div
      aria-hidden
      className={`pointer-events-none absolute -z-10 rounded-[2.5rem] blur-3xl ${!reduced && breathe ? "pv-glow-breathe" : ""} ${className}`}
      style={{ background: gradient }}
    />
  );
}

/* ── Hero centerpiece: one-click setup → live site (friendly, no terminal) ─── */
function InstallToLive() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const [installed, setInstalled] = useState(0);
  const [phase, setPhase] = useState<"idle" | "installing" | "live">("idle");
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    if (!seen) return;
    if (reduced) {
      setInstalled(INSTALL_STEPS.length);
      setPhase("live");
      return;
    }
    let dead = false;
    const push = (fn: () => void, ms: number) => {
      if (!dead) timers.current.push(setTimeout(fn, ms));
    };
    const run = () => {
      setInstalled(0);
      setPhase("installing");
      INSTALL_STEPS.forEach((_, i) => push(() => setInstalled(i + 1), 600 + 720 * (i + 1)));
      const done = 600 + 720 * (INSTALL_STEPS.length + 1);
      push(() => setPhase("live"), done);
      push(run, done + 5200); // loop
    };
    run();
    return () => {
      dead = true;
      timers.current.forEach(clearTimeout);
      timers.current = [];
    };
  }, [seen, reduced]);

  const live = phase === "live";
  const pct = Math.round((installed / INSTALL_STEPS.length) * 100);

  return (
    <div ref={ref} className="relative">
      <AuraGlow
        className="-inset-10"
        gradient="radial-gradient(42% 42% at 12% 8%, rgba(59,130,246,0.30), transparent 72%), radial-gradient(46% 50% at 92% 96%, rgba(111,71,245,0.32), transparent 72%)"
      />

      <div className={reduced ? "" : "pv-float-slow"}>
        <div className="grid gap-4 sm:grid-cols-[0.92fr_1.08fr] sm:items-start">
          {/* friendly setup card */}
          <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-navy-900/85 shadow-2xl shadow-black/50 backdrop-blur-xl">
            <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
              <span className="flex h-6 w-6 items-center justify-center rounded-md bg-gradient-to-br from-accent-blue to-brand-500 text-white">
                <IconApps size={13} />
              </span>
              <span className="text-[12px] font-medium text-slate-300">Setting up your site</span>
              <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-medium text-emerald-300">
                <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
                {live ? "all done" : "working…"}
              </span>
            </div>
            <div className="space-y-3 px-4 py-4">
              <div className="flex items-center gap-2.5 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
                <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-white/[0.04] text-brand-300">
                  <IconApps size={18} />
