  const barPct = (v: number) => `${(v / maxVal) * CEIL}%`;
  const flatTop = (PRICE_YEARS[0].nxeon / maxVal) * CEIL;

  return (
    <div ref={ref} className="grid gap-10 lg:grid-cols-2 lg:items-center lg:gap-14">
      <div>
        <span className="eyebrow">No renewal price hikes</span>
