          className="-inset-6"
          gradient="radial-gradient(55% 60% at 70% 20%, rgba(34,211,238,0.16), transparent 70%), radial-gradient(50% 55% at 20% 90%, rgba(111,71,245,0.20), transparent 70%)"
        />
        <div className="relative overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-900/60 p-6 backdrop-blur-md">
