          >
            {/* gridlines */}
            {[22, 44, 66, 88].map((t) => (
              <div key={t} className="absolute inset-x-0 border-t border-white/[0.045]" style={{ bottom: `${t}%` }} aria-hidden />
            ))}
            {/* baseline */}
            <div className="absolute inset-x-0 bottom-0 border-t border-white/10" aria-hidden />

            {/* flat-forever guide line at Nxeon's height */}
