/* ── cPanel-class control panel product screen (friendly, not a terminal) ──── */
function ControlPanelScreen() {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const visitors = useCountUp(3420, seen, 1300, reduced);
  const nav = ["Dashboard", "Websites", "Files", "Databases", "Email", "Domains", "SSL", "Backups"];

  // tiny sparkline
  const pts = [8, 10, 9, 12, 11, 14, 13, 16, 15, 18, 17, 20];
  const w = 120;
  const sh = 34;
