  const max = 22;
  const step = w / (pts.length - 1);
  const line = pts
    .map((v, i) => `${i === 0 ? "M" : "L"}${(i * step).toFixed(1)} ${(sh - ((v - min) / (max - min)) * sh).toFixed(1)}`)
    .join(" ");

  return (
    <div ref={ref} className="relative">
      <AuraGlow
        className="-inset-8"
        gradient="radial-gradient(45% 50% at 15% 5%, rgba(59,130,246,0.22), transparent 70%), radial-gradient(45% 55% at 90% 100%, rgba(111,71,245,0.24), transparent 70%)"
