              <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-3">
                <p className="text-[10px] uppercase tracking-wide text-slate-500">Visitors · 30d</p>
                <p className="mt-1 font-mono text-sm font-semibold text-white tabular-nums">{visitors.toLocaleString()}</p>
