function FeatureCard({ f, delay }: { f: (typeof FEATURES)[number]; delay: number }) {
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  return (
    <div
      ref={ref}
      className={`group relative overflow-hidden rounded-2xl border border-white/[0.07] bg-navy-900/50 p-6 transition-all duration-700 ease-out hover:border-white/15 ${
        seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"
      }`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      <span className="flex h-11 w-11 items-center justify-center rounded-xl border border-white/10 bg-gradient-to-br from-brand-500/25 to-transparent text-brand-300">
        <FeatureIcon icon={f.icon} size={20} />
      </span>
      <h3 className="mt-5 text-base font-semibold text-white">{f.title}</h3>
      <p className="mt-2 text-sm leading-relaxed text-slate-400">{f.body}</p>
    </div>
  );
}

